import * as React from 'react';
import './kbd.css';

/* KEYCAP (Kamui 04 §9). Static: a key is shown, never pressed. Glyphs only: ⌘ ⌥ ⇧ ⌃ ⎋ ↩ ⌫ ↑ ↓, letters. */

export interface KbdProps extends React.HTMLAttributes<HTMLElement> {
  /** small (16) for a dense footer; default 20. */
  size?: 'default' | 'small';
  /** Where the cap sits: on a light surface (default), a graphite strip, or sunk into a toast's Undo. */
  surface?: 'default' | 'strip' | 'sunk';
  /** What assistive tech should say, when the glyph is not a word: "Command K". */
  label?: string;
}

const NAMES: Record<string, string> = { '⌘': 'Command', '⌥': 'Option', '⇧': 'Shift', '⌃': 'Control', '⎋': 'Escape', '↩': 'Return', '⌫': 'Delete', '↑': 'Up', '↓': 'Down', '←': 'Left', '→': 'Right' };

/** A key, on a small raised cap. */
export const Kbd = React.forwardRef<HTMLElement, KbdProps>(function Kbd({ size = 'default', surface = 'default', label, className, children, ...props }, ref) {
  const text = typeof children === 'string' ? children : '';
  const spoken = label ?? (text && [...text].some((c) => NAMES[c]) ? [...text].map((c) => NAMES[c] ?? c).join(' ') : undefined);
  return (
    <kbd ref={ref} data-size={size} data-surface={surface} aria-label={spoken} className={className ? `mu-kbd ${className}` : 'mu-kbd'} {...props}>
      {children}
    </kbd>
  );
});

@import "../tokens.css";

/* Keycap (the reference design's kbd). Its look is the kbd recipe (--mu-r-kbd-*). */
.mu-kbd {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: var(--mu-r-kbd-self-min);
  height: var(--mu-r-kbd-self-height);
  padding: var(--mu-zero) var(--mu-r-kbd-self-pad);
  border-radius: var(--mu-r-kbd-self-radius);
  font: var(--mu-r-kbd-self-font);
  letter-spacing: var(--mu-r-kbd-self-tracking);
  color: var(--mu-ink2);
  background: var(--mu-r-kbd-self-background);
  box-shadow: var(--mu-r-kbd-self-shadow);
  white-space: nowrap;
  vertical-align: middle;
}
.mu-kbd[data-size="small"] { min-width: var(--mu-r-kbd-small-min); height: var(--mu-r-kbd-small-height); padding: var(--mu-zero) var(--mu-r-kbd-small-pad); border-radius: var(--mu-r-kbd-small-radius); }
.mu-kbd[data-surface="strip"] { color: var(--mu-r-kbd-strip-ink); background: var(--mu-r-kbd-strip-background); box-shadow: var(--mu-r-kbd-strip-shadow); }
.mu-kbd[data-surface="sunk"] { color: var(--mu-r-kbd-sunk-ink); background: var(--mu-r-kbd-sunk-background); box-shadow: var(--mu-r-kbd-sunk-shadow); border-radius: var(--mu-radius-pill); }
.mu-kbd + .mu-kbd { margin-left: var(--mu-r-kbd-self-gap); }
